'use client';

import { useEffect, useRef, useState, type CSSProperties } from 'react';
import './undo-banner.css';

export interface UndoBannerProps {
  message: string;
  onUndo: () => void;
  /** Called when the banner is closed or runs out of time. */
  onDismiss: () => void;
  /** Time before it disappears, in milliseconds. Paused while hovered or focused. */
  duration?: number;
  className?: string;
}

/**
 * An inline notice with Undo after something is removed. It never takes
 * focus; it counts down (paused while the pointer or focus is on it) and then
 * goes away by itself.
 */
export function UndoBanner({
  message,
  onUndo,
  onDismiss,
  duration = 6000,
  className = '',
}: UndoBannerProps) {
  const [held, setHeld] = useState(false);
  const left = useRef(duration);
  const dismiss = useRef(onDismiss);
  dismiss.current = onDismiss;

  useEffect(() => {
    if (held) return;
    const started = Date.now();
    const timer = window.setTimeout(() => dismiss.current(), left.current);
    return () => {
      window.clearTimeout(timer);
      left.current = Math.max(0, left.current - (Date.now() - started));
    };
  }, [held]);

  return (
    <div
      className={`mg-undo ${className}`}
      role='status'
      data-held={held}
      style={{ '--mg-duration': `${duration}ms` } as CSSProperties}
      onPointerEnter={() => setHeld(true)}
      onPointerLeave={() => setHeld(false)}
      onFocus={() => setHeld(true)}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node))
          setHeld(false);
      }}
    >
      <span className='mg-undo__text'>{message}</span>
      <button type='button' className='mg-undo__undo' onClick={onUndo}>
        Undo
      </button>
      <button
        type='button'
        className='mg-undo__close'
        aria-label='Dismiss'
        onClick={onDismiss}
      >
        <svg width='16' height='16' viewBox='0 0 16 16' aria-hidden='true'>
          <path
            d='M4 4l8 8M12 4l-8 8'
            fill='none'
            stroke='currentColor'
            strokeWidth='1.75'
            strokeLinecap='round'
          />
        </svg>
      </button>
      <span className='mg-undo__timer' aria-hidden='true' />
    </div>
  );
}

.mg-undo {
  position: relative;
  display: flex;
  align-items: center;
  gap: 6px;
  overflow: hidden;
  padding: 4px 4px 4px 14px;
  border-radius: 10px;
  background: var(--mg-raised, #262626);
  color: #fff;
  font-size: 14px;
  animation: mg-undo-in 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-undo__text {
  flex: 1;
  min-width: 0;
}

.mg-undo__undo,
.mg-undo__close {
  flex: none;
  min-width: 44px;
  min-height: 44px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.mg-undo__undo {
  padding: 0 10px;
  color: var(--mg-accent-text, #ffffff);
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.mg-undo__close {
  font-size: 20px;
}

.mg-undo__undo:focus-visible,
.mg-undo__close:focus-visible {
  outline: 2px solid var(--mg-accent-text, #dce9f7);
  outline-offset: -2px;
}

/* Time left, as a shrinking bar along the bottom edge. */
.mg-undo__timer {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 3px;
  background: var(--mg-accent, #eaf2fb);
  transform-origin: left;
  animation: mg-undo-timer var(--mg-duration) linear forwards;
}

.mg-undo[data-held='true'] .mg-undo__timer {
  animation-play-state: paused;
}

@keyframes mg-undo-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

@keyframes mg-undo-timer {
  to {
    transform: scaleX(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-undo {
    animation: none;
  }
}
